/* Small WebAudio chiptune kit: synthesized SFX plus a gentle arpeggio loop. */

export class SoundKit {
  constructor() {
    this.ctx = null
    this.master = null
    this.musicGain = null
    this.enabled = true
    this.musicTimer = null
    this.step = 0
    this.noiseBuffer = null
  }

  ensure() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume()
      return
    }
    const Ctx = window.AudioContext || window.webkitAudioContext
    if (!Ctx) return
    this.ctx = new Ctx()
    this.master = this.ctx.createGain()
    this.master.gain.value = this.enabled ? 0.75 : 0
    this.master.connect(this.ctx.destination)
    this.musicGain = this.ctx.createGain()
    this.musicGain.gain.value = 0.12
    this.musicGain.connect(this.master)

    const length = this.ctx.sampleRate * 0.8
    this.noiseBuffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate)
    const data = this.noiseBuffer.getChannelData(0)
    for (let i = 0; i < length; i++) data[i] = Math.random() * 2 - 1
  }

  setEnabled(on) {
    this.enabled = on
    if (!this.ctx) return
    this.master.gain.setTargetAtTime(on ? 0.75 : 0, this.ctx.currentTime, 0.03)
    if (!on) this.stopMusic()
  }

  tone(freq, duration = 0.1, type = 'square', volume = 0.045, slide = 0, delay = 0) {
    if (!this.enabled || !this.ctx) return
    const start = this.ctx.currentTime + delay
    const osc = this.ctx.createOscillator()
    const gain = this.ctx.createGain()
    osc.type = type
    osc.frequency.setValueAtTime(freq, start)
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), start + duration)
    gain.gain.setValueAtTime(0.0001, start)
    gain.gain.exponentialRampToValueAtTime(volume, start + 0.012)
    gain.gain.exponentialRampToValueAtTime(0.0001, start + duration)
    osc.connect(gain).connect(this.master)
    osc.start(start)
    osc.stop(start + duration + 0.02)
  }

  noise(duration = 0.25, volume = 0.12, highpass = 500) {
    if (!this.enabled || !this.ctx || !this.noiseBuffer) return
    const start = this.ctx.currentTime
    const src = this.ctx.createBufferSource()
    src.buffer = this.noiseBuffer
    const filter = this.ctx.createBiquadFilter()
    filter.type = 'highpass'
    filter.frequency.value = highpass
    const gain = this.ctx.createGain()
    gain.gain.setValueAtTime(volume, start)
    gain.gain.exponentialRampToValueAtTime(0.0001, start + duration)
    src.connect(filter).connect(gain).connect(this.master)
    src.start(start)
    src.stop(start + duration)
  }

  select() { this.tone(720, 0.05, 'square', 0.025) }
  swap() { this.tone(420, 0.07, 'triangle', 0.05, 220) }
  invalid() {
    this.tone(180, 0.1, 'sawtooth', 0.05, -60)
    this.tone(140, 0.13, 'square', 0.035, -40, 0.08)
  }
  match(combo = 1) {
    const base = 440 * Math.pow(2, Math.min(combo - 1, 6) / 12)
    this.tone(base, 0.09, 'square', 0.045)
    this.tone(base * 1.25, 0.08, 'square', 0.035, 0, 0.06)
    this.tone(base * 1.5, 0.11, 'triangle', 0.035, 0, 0.12)
  }
  special() {
    ;[523, 659, 784, 1047].forEach((note, i) => this.tone(note, 0.12, 'square', 0.04, 0, i * 0.045))
  }
  explode() {
    this.noise(0.4, 0.16, 250)
    this.tone(90, 0.35, 'sawtooth', 0.09, -50)
  }
  bossHit() {
    this.tone(120, 0.12, 'square', 0.06, -40)
    this.tone(70, 0.18, 'sawtooth', 0.05, -25, 0.03)
  }
  bossAttack() {
    this.noise(0.3, 0.06, 120)
    this.tone(60, 0.4, 'sawtooth', 0.06, -15)
  }
  ready() {
    this.tone(660, 0.09, 'square', 0.05)
    this.tone(880, 0.12, 'square', 0.05, 0, 0.09)
    this.tone(1175, 0.16, 'triangle', 0.04, 0, 0.19)
  }
  victory() {
    const notes = [523, 659, 784, 1047, 1319, 1568]
    notes.forEach((note, i) => this.tone(note, 0.2, 'square', 0.045, 0, i * 0.11))
    this.tone(523, 0.55, 'triangle', 0.05, 0, 0.66)
    this.tone(784, 0.55, 'triangle', 0.04, 0, 0.66)
  }
  levelUp() {
    const notes = [392, 523, 659, 784]
    notes.forEach((note, i) => this.tone(note, 0.16, 'square', 0.05, 0, i * 0.1))
  }

  startMusic() {
    if (!this.enabled || !this.ctx || this.musicTimer) return
    const scale = [261.63, 329.63, 392.0, 523.25, 659.25, 523.25, 392.0, 329.63]
    const bass = [130.81, 130.81, 174.61, 196.0]
    this.musicTimer = setInterval(() => {
      if (!this.enabled || !this.ctx) return
      const note = scale[this.step % scale.length]
      const when = this.step % 8
      const osc = this.ctx.createOscillator()
      const gain = this.ctx.createGain()
      osc.type = 'triangle'
      osc.frequency.value = note * (when > 4 ? 2 : 1)
      const start = this.ctx.currentTime + 0.02
      gain.gain.setValueAtTime(0.0001, start)
      gain.gain.exponentialRampToValueAtTime(0.035, start + 0.01)
      gain.gain.exponentialRampToValueAtTime(0.0001, start + 0.19)
      osc.connect(gain).connect(this.musicGain)
      osc.start(start)
      osc.stop(start + 0.22)
      if (this.step % 4 === 0) {
        const b = this.ctx.createOscillator()
        const bg = this.ctx.createGain()
        b.type = 'sine'
        b.frequency.value = bass[Math.floor(this.step / 4) % bass.length]
        bg.gain.setValueAtTime(0.0001, start)
        bg.gain.exponentialRampToValueAtTime(0.05, start + 0.02)
        bg.gain.exponentialRampToValueAtTime(0.0001, start + 0.42)
        b.connect(bg).connect(this.musicGain)
        b.start(start)
        b.stop(start + 0.45)
      }
      this.step++
    }, 265)
  }

  stopMusic() {
    if (this.musicTimer) clearInterval(this.musicTimer)
    this.musicTimer = null
  }
}

@font-face {
  font-family: 'Press Start 2P';
  src: url('./assets/fonts/press-start-2p.woff2') format('woff2');
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Silkscreen';
  src: url('./assets/fonts/silkscreen.woff2') format('woff2');
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Silkscreen';
  src: url('./assets/fonts/silkscreen-bold.woff2') format('woff2');
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}

:root {
  --pixel: 'Press Start 2P', 'Courier New', monospace;
  --ui: 'Silkscreen', 'Courier New', monospace;
  --ink: #241733;
  --ink-deep: #140c22;
  --panel: rgba(43, 27, 66, 0.92);
  --panel-soft: rgba(52, 33, 80, 0.82);
  --cream: #fff4d9;
  --gold: #ffd257;
  --gold-hot: #ffe89b;
  --pink: #ff4d8d;
  --orange: #ff7a2f;
  --mint: #57e0b4;
  --red: #ff4b45;
  --sky: #74cdf3;
  --safe-top: max(14px, env(safe-area-inset-top));
  --safe-bottom: max(14px, env(safe-area-inset-bottom));
}

* { box-sizing: border-box; }

html, body {
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: #7bd0f2;
  overscroll-behavior: none;
}

body {
  font-family: var(--ui);
  color: var(--cream);
  -webkit-font-smoothing: none;
  text-rendering: geometricPrecision;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
}

button { font-family: inherit; }

.svg-defs { position: absolute; width: 0; height: 0; overflow: hidden; }

.icon {
  width: 1em;
  height: 1em;
  display: block;
  fill: currentColor;
  shape-rendering: crispEdges;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background:
    linear-gradient(180deg, #52b9ec 0%, #8dd9f8 38%, #c9f0ff 63%, #ffe5bf 100%);
}

.sky-glow {
  position: absolute;
  inset: -20% -10% auto -10%;
  height: 75%;
  background: radial-gradient(ellipse at 50% 15%, rgba(255, 247, 208, 0.72), rgba(255, 247, 208, 0) 58%);
  pointer-events: none;
}

#stage {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  outline: none;
}

.vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 46%, rgba(255, 255, 255, 0) 44%, rgba(25, 12, 40, 0.26) 100%),
    linear-gradient(180deg, rgba(20, 8, 35, 0.14), transparent 18%, transparent 82%, rgba(20, 8, 35, 0.22));
  mix-blend-mode: multiply;
}

.target-vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.22s ease;
  background: radial-gradient(ellipse at 50% 50%, rgba(255, 140, 40, 0) 48%, rgba(255, 70, 30, 0.38) 100%);
  box-shadow: inset 0 0 80px rgba(255, 90, 20, 0.6);
}
#app.is-targeting .target-vignette { opacity: 1; }
#app.is-targeting #stage { cursor: crosshair; }

.flash {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  background: radial-gradient(circle at 50% 50%, #fff8c9, #ff9a3c 55%, rgba(255, 90, 20, 0) 78%);
  mix-blend-mode: screen;
}
.flash.pop { animation: flash-pop 0.5s ease-out; }
@keyframes flash-pop {
  0% { opacity: 0; }
  18% { opacity: 0.85; }
  100% { opacity: 0; }
}

.hud {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 10;
}
.hud button { pointer-events: auto; }

/* ---------------- Top bar ---------------- */

.topbar {
  position: absolute;
  top: var(--safe-top);
  left: 18px;
  right: 18px;
  display: grid;
  grid-template-columns: minmax(250px, 1fr) auto minmax(320px, 1fr);
  align-items: start;
  gap: 14px;
}

.brand { width: max-content; filter: drop-shadow(0 5px 0 rgba(20, 12, 34, 0.35)); }
.brand-eyebrow {
  display: block;
  font-family: var(--pixel);
  font-size: 7px;
  letter-spacing: 2.6px;
  color: #2d2a5c;
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.55);
  margin: 0 0 7px 3px;
}
.brand-title {
  display: flex;
  align-items: baseline;
  font-family: var(--pixel);
  font-size: clamp(19px, 2.1vw, 29px);
  line-height: 0.95;
  letter-spacing: -1px;
}
.candy-word { color: var(--cream); text-shadow: 3px 3px 0 #b1265f, 6px 6px 0 rgba(36, 23, 51, 0.55); }
.craft-word { color: var(--gold); margin-left: 7px; text-shadow: 3px 3px 0 #d2611f, 6px 6px 0 rgba(36, 23, 51, 0.55); }
.brand-sub {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 8px;
  padding: 5px 9px 4px;
  font-family: var(--pixel);
  font-size: 6.5px;
  letter-spacing: 1.5px;
  color: var(--cream);
  background: #2a1a44;
  border: 2px solid #150d22;
  box-shadow: inset 0 0 0 2px rgba(255, 210, 87, 0.42), 0 3px 0 rgba(20, 12, 34, 0.5);
}
.brand-sub .icon { width: 11px; height: 11px; color: var(--orange); }

.stats { display: flex; gap: 8px; padding-top: 2px; }
.stat {
  min-width: 92px;
  padding: 7px 10px 5px;
  background: linear-gradient(180deg, rgba(58, 37, 88, 0.95), rgba(35, 22, 54, 0.95));
  border: 2px solid var(--ink-deep);
  box-shadow: inset 0 0 0 2px rgba(255, 210, 87, 0.26), 0 4px 0 rgba(20, 12, 34, 0.55);
  text-align: center;
}
.stat-label { display: block; font-family: var(--pixel); font-size: 5.5px; letter-spacing: 1.4px; color: #ffcf73; margin-bottom: 5px; }
.stat strong { display: block; font-family: var(--pixel); font-size: 14px; line-height: 1; color: #fff; text-shadow: 0 2px 0 #7a2c60; }

