  .sound-toggle { width: 16px; height: 16px; border-width: 1px; }
  .sound-toggle .icon { width: 9px; height: 9px; }
  .pup-meter { height: 10px; }
  .pup-note { font-size: 3.4px; letter-spacing: 0.5px; margin-top: 3px; }
  .fire-btn { grid-area: fire; min-width: 0; width: 142px; height: 52px; padding: 0 8px 0 6px; gap: 6px; border-width: 2px; box-shadow: inset 0 0 0 1px rgba(255, 244, 200, 0.6), 0 4px 0 #7d1c2e; }
  .fire-btn-icon { flex-basis: 28px; width: 28px; height: 28px; border-width: 1px; }
  .fire-btn-icon .icon { width: 19px; height: 19px; }
  .fire-btn-text strong { font-size: 6.5px; text-shadow: 0 1px 0 #7d1c2e; }
  .fire-btn-text small { font-size: 3.6px; letter-spacing: 0.4px; }
  .hotbar-wrap { grid-area: bag; display: block; justify-self: center; }
  .hotbar-label { display: none; }
  .hotbar { padding: 3px; gap: 3px; border-width: 2px; box-shadow: inset 0 0 0 1px rgba(255, 210, 87, 0.2), 0 3px 0 rgba(20, 12, 34, 0.35); }
  .slot { width: 37px; height: 37px; border-width: 1px; }
