  .float-text { font-size: 8px; }
  .start-card { width: 94vw; padding: 22px 16px 20px; }
  .start-card h1 { font-size: clamp(26px, 8.4vw, 40px); gap: 5px; }
  .start-card h1 .candy-word, .start-card h1 .craft-word { text-shadow: 3px 3px 0 #b1265f, 6px 6px 0 rgba(12, 6, 22, 0.6); }
