  .levelup-kicker { font-size: 4.5px; letter-spacing: 1.6px; }
  .levelup-sub { font-size: 4.5px; }
}

@media (max-height: 620px) and (orientation: landscape) {
  .quest, .hint, .hotbar-wrap { display: none; }
  .topbar { grid-template-columns: 1fr auto minmax(260px, 1fr); grid-template-areas: "brand stats boss"; align-items: start; }
  .boss-card { grid-area: boss; width: 290px; margin-left: auto; }
