  if (!move) return
  hintRings.children[0].position.set(cellX(move.c1), 0.33, cellZ(move.r1))
  hintRings.children[1].position.set(cellX(move.c2), 0.33, cellZ(move.r2))
  hintRings.visible = true
  state.hintTimer = 0
