  const h = window.innerHeight
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.75))
  renderer.setSize(w, h, false)
  const mobile = w < 720
  camera.aspect = w / h
  camera.fov = mobile ? 50 : 32
  const fitWidth = mobile ? 10.8 : 18
  const dist = (fitWidth / 2) / (Math.tan(THREE.MathUtils.degToRad(camera.fov / 2)) * camera.aspect)
  const elevation = THREE.MathUtils.degToRad(mobile ? 57 : 37)
  camTarget.set(0, mobile ? 0.05 : 0.35, mobile ? -0.55 : 0)
  camBase.set(0, Math.sin(elevation) * dist + (mobile ? 0.3 : 0.7), Math.cos(elevation) * dist)
  camera.position.copy(camBase)
  camera.lookAt(camTarget)
  camera.updateProjectionMatrix()
  camera.updateMatrixWorld()

  if (mobile) {
    const small = w < 470
    pupRoot.position.set(-3.65, 0.6, -5.55)
    pupRoot.scale.setScalar(small ? 0.52 : 0.62)
    pupRoot.rotation.y = 0.28
    golemRoot.position.set(3.65, 0.6, -5.55)
    golemRoot.scale.setScalar(small ? 0.57 : 0.68)
    golemRoot.rotation.y = -0.28
  } else {
    pupRoot.position.set(-6.75, 0.55, 0.45)
    pupRoot.scale.setScalar(0.96)
    pupRoot.rotation.y = 0.42
    golemRoot.position.set(6.85, 0.55, 0.45)
    golemRoot.scale.setScalar(1.04)
    golemRoot.rotation.y = -0.45
  }
