const { createRequire } = require('node:module');
const { join } = require('node:path');
const { readFileSync } = require('node:fs');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const project = (r, c) => {
  const d = window.__candyDebug;
  const rect = d.stage.getBoundingClientRect();
  const v = d.cellPos(r, c).project(d.camera);
  return { x: rect.left + (v.x * 0.5 + 0.5) * rect.width, y: rect.top + (-v.y * 0.5 + 0.5) * rect.height };
};

async function run(browser, name, contextOptions, mode) {
  const ctx = await browser.newContext(contextOptions);
  const page = await ctx.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForTimeout(1100);
  await page.locator('#startBtn').click();
  await page.waitForTimeout(900);

  const swap = await page.evaluate(() => {
    const d = window.__candyDebug;
    const g = d.typeGrid();
    return d.findSwap(g.map(row => row.slice()));
  });
  console.log(name, 'planned swap', JSON.stringify(swap));

  const pts = await page.evaluate(({ a, b }) => {
    const project = (r, c) => {
      const d = window.__candyDebug;
      const rect = d.stage.getBoundingClientRect();
      const v = d.cellPos(r, c).project(d.camera);
      return { x: rect.left + (v.x * 0.5 + 0.5) * rect.width, y: rect.top + (-v.y * 0.5 + 0.5) * rect.height };
    };
    return { a: project(a.r1, a.c1), b: project(a.r2, a.c2) };
  }, { a: swap, b: swap });

  if (mode === 'drag') {
    await page.mouse.move(pts.a.x, pts.a.y);
    await page.mouse.down();
    await page.mouse.move((pts.a.x + pts.b.x) / 2, (pts.a.y + pts.b.y) / 2, { steps: 6 });
    await page.mouse.move(pts.b.x, pts.b.y, { steps: 6 });
    await page.mouse.up();
  } else if (mode === 'touch') {
    await page.touchscreen.tap(pts.a.x, pts.a.y);
    await page.waitForTimeout(120);
    await page.touchscreen.tap(pts.b.x, pts.b.y);
  } else {
    await page.mouse.click(pts.a.x, pts.a.y);
    await page.waitForTimeout(120);
    await page.mouse.click(pts.b.x, pts.b.y);
  }

  await page.waitForTimeout(1400);
  const state = await page.evaluate(() => {
    const s = window.__candyDebug.state;
    return { moves: s.moves, score: s.score, bossHp: s.boss.hp, playing: s.playing, busy: s.busy };
  });
  console.log(name, JSON.stringify(state), 'pts', JSON.stringify(pts));

  // Try a second input the opposite way: drag on desktop, taps on mobile.
  const swap2 = await page.evaluate(() => {
    const d = window.__candyDebug;
    return d.findSwap(d.typeGrid().map(row => row.slice()));
  });
  if (swap2) {
    const pts2 = await page.evaluate((a) => {
      const project = (r, c) => {
        const d = window.__candyDebug;
        const rect = d.stage.getBoundingClientRect();
        const v = d.cellPos(r, c).project(d.camera);
        return { x: rect.left + (v.x * 0.5 + 0.5) * rect.width, y: rect.top + (-v.y * 0.5 + 0.5) * rect.height };
      };
      return { a: project(a.r1, a.c1), b: project(a.r2, a.c2) };
    }, swap2);
    if (mode === 'touch') {
      await page.touchscreen.tap(pts2.a.x, pts2.a.y);
      await page.waitForTimeout(120);
      await page.touchscreen.tap(pts2.b.x, pts2.b.y);
    } else {
      await page.mouse.move(pts2.a.x, pts2.a.y);
      await page.mouse.down();
      await page.mouse.move(pts2.b.x, pts2.b.y, { steps: 8 });
      await page.mouse.up();
    }
    await page.waitForTimeout(1400);
    const state2 = await page.evaluate(() => {
      const s = window.__candyDebug.state;
      return { moves: s.moves, score: s.score, playing: s.playing, busy: s.busy };
    });
    console.log(name, 'second', JSON.stringify(state2));
  }
  await page.screenshot({ path: `screenshots/input-${name}.png` });
  console.log(name, 'errors:', errors.slice(0, 6));
  await ctx.close();
}

(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  await run(browser, 'desktop', { viewport: { width: 1440, height: 900 } }, 'click');
  await run(browser, 'mobile', { viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 }, 'touch');
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

