      const d = window.__candyDebug;
      const rect = d.stage.getBoundingClientRect();
      d.camera.updateMatrixWorld();
      const p = (v) => {
        const q = v.clone().project(d.camera);
        return { x: Math.round((q.x * 0.5 + 0.5) * rect.width), y: Math.round((-q.y * 0.5 + 0.5) * rect.height), z: +q.z.toFixed(2) };
      };
      return {
        cam: p(d.camera.position.clone().set(0, 0, 0)),
        clouds: d.clouds.map(c => ({ pos: c.position.toArray().map(n => +n.toFixed(1)), screen: p(c.position), visible: c.visible })),
        boardTop: p(new (d.camera.position.constructor)(0, 0.78, -4.48)),
        boardBottom: p(new (d.camera.position.constructor)(0, 0.78, 4.48)),
      };
    });
    console.log(name, JSON.stringify(out, null, 1));
    await ctx.close();
  }
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

