const { createRequire } = require('node:module');
const { join } = require('node:path');
const { readFileSync } = require('node:fs');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  for (const [name, width, height, mobile] of [['desktop', 1440, 900, false], ['mobile', 390, 844, true]]) {
    const ctx = await browser.newContext({ viewport: { width, height }, isMobile: mobile, hasTouch: mobile, deviceScaleFactor: mobile ? 2 : 1 });
    const page = await ctx.newPage();
    const errors = [];
    page.on('pageerror', e => errors.push(e.message));
    page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
    await page.goto('http://localhost:4173', { waitUntil: 'load', timeout: 45000 });
    await page.waitForTimeout(1100);
    const label = await page.locator('#startBtn').innerText();
    console.log(name, 'start:', JSON.stringify(label), 'visible:', await page.locator('#startBtn').isVisible());
    await page.locator('#startBtn').click({ timeout: 10000 });
    await page.waitForTimeout(1200);
    // Tap a few board cells to prove input is live without the debug hook.
    const box = await page.locator('#stage').boundingBox();
    if (mobile) {
      await page.touchscreen.tap(box.x + box.width * 0.45, box.y + box.height * 0.55);
      await page.waitForTimeout(120);
      await page.touchscreen.tap(box.x + box.width * 0.45, box.y + box.height * 0.62);
    } else {
      await page.mouse.click(box.x + box.width * 0.45, box.y + box.height * 0.55);
      await page.waitForTimeout(120);
      await page.mouse.click(box.x + box.width * 0.45, box.y + box.height * 0.62);
    }
    await page.waitForTimeout(900);
    const prodDebug = await page.evaluate(() => typeof window.__candyDebug);
    await page.screenshot({ path: `screenshots/prod-${name}.png` });
    console.log(name, 'debug:', prodDebug, 'errors:', errors.slice(0, 6));
    await ctx.close();
  }
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
EOF
